
import React, { useEffect, useRef } from "react";

const auraStyle = {
	position: "fixed",
	left: 0,
	top: 0,
	pointerEvents: "none",
	zIndex: 9999,
	width: 60,
	height: 60,
	borderRadius: "50%",
	background: "radial-gradient(circle, rgba(255,0,0,0.18) 0%, rgba(0,0,255,0.12) 100%)",
	boxShadow: "0 0 32px 8px #e53e3e55",
	transition: "transform 0.15s cubic-bezier(.17,.67,.83,.67)",
	mixBlendMode: "multiply",
};

const BackgroundCursorAura = () => {
	const auraRef = useRef(null);

	useEffect(() => {
		const moveAura = (e) => {
			if (auraRef.current) {
				auraRef.current.style.transform = `translate(${e.clientX - 30}px, ${e.clientY - 30}px)`;
			}
		};
		window.addEventListener("mousemove", moveAura);
		return () => window.removeEventListener("mousemove", moveAura);
	}, []);

	return <div ref={auraRef} style={auraStyle}></div>;
};

export default BackgroundCursorAura;
