
import React, { useState } from 'react';
import './Header.css';
import { Link } from 'react-router-dom';
import logo from '../logo.svg';

function Header() {
	const [menuOpen, setMenuOpen] = useState(false);
	   return (
		<header className="glass-header" style={{ background: '#e53e3e' }}>
			   <div className="brand flex items-center gap-6 py-2">
				   <img src={logo} alt="Urja Dental Clinic Logo" className="brand-logo" style={{ height: '96px', width: '96px', minWidth: '96px' }} />
				   <div className="flex flex-col">
					   <span className="brand-name text-3xl md:text-4xl font-extrabold tracking-wide leading-tight" style={{ color: '#fff', fontWeight: 'bold', letterSpacing: '0.04em', textShadow: '0 1px 4px rgba(0,0,0,0.15)' }}>Urja Multispeciality</span>
					   <span className="brand-name text-2xl md:text-3xl font-bold tracking-wide leading-tight" style={{ color: '#fff', fontWeight: 'bold', letterSpacing: '0.04em', textShadow: '0 1px 4px rgba(0,0,0,0.15)' }}>Dental Clinic</span>
				   </div>
			   </div>
			<button className="menu-toggle" onClick={() => setMenuOpen(!menuOpen)} aria-label="Toggle menu">
				<span>&#9776;</span>
			</button>
						<nav className={`nav-menu${menuOpen ? ' open' : ''}`}>
							<Link to="/" className="nav-link" style={{cursor:'pointer'}} onClick={() => setMenuOpen(false)}>Home</Link>
							<div className="nav-link dropdown-trigger" style={{ position: 'relative', cursor: 'pointer' }}>
								<span>Our Services &#9662;</span>
								<div className="dropdown-menu" style={{ position: 'absolute', left: 0, top: '100%', background: '#fff', borderRadius: '12px', boxShadow: '0 4px 24px rgba(0,0,0,0.08)', minWidth: '220px', zIndex: 100, whiteSpace: 'nowrap', padding: '0.5rem 0.5rem', pointerEvents: 'auto' }}>
									<ul style={{ margin: 0, padding: 0, listStyle: 'none' }}>
										<li style={{padding:'0.25rem 0'}}><Link to="/anti-snoring" className="nav-link" style={{cursor:'pointer', whiteSpace:'nowrap', width:'100%', display:'inline-block'}} onClick={() => setMenuOpen(false)}>Anti Snoring</Link></li>
										<li style={{padding:'0.25rem 0'}}><Link to="/braces-treatment" className="nav-link" style={{cursor:'pointer', whiteSpace:'nowrap', width:'100%', display:'inline-block'}} onClick={() => setMenuOpen(false)}>Braces Treatment</Link></li>
										<li style={{padding:'0.25rem 0'}}><Link to="/dental-tooth-implant" className="nav-link" style={{cursor:'pointer', whiteSpace:'nowrap', width:'100%', display:'inline-block'}} onClick={() => setMenuOpen(false)}>Dental Tooth Implant</Link></li>
										<li style={{padding:'0.25rem 0'}}><Link to="/dentures" className="nav-link" style={{cursor:'pointer', whiteSpace:'nowrap', width:'100%', display:'inline-block'}} onClick={() => setMenuOpen(false)}>Dentures</Link></li>
										<li style={{padding:'0.25rem 0'}}><Link to="/diamond-on-tooth" className="nav-link" style={{cursor:'pointer', whiteSpace:'nowrap', width:'100%', display:'inline-block'}} onClick={() => setMenuOpen(false)}>Diamond On Tooth</Link></li>
										<li style={{padding:'0.25rem 0'}}><Link to="/full-mouth-dental-crown" className="nav-link" style={{cursor:'pointer', whiteSpace:'nowrap', width:'100%', display:'inline-block'}} onClick={() => setMenuOpen(false)}>Full Mouth Dental Crown</Link></li>
										<li style={{padding:'0.25rem 0'}}><Link to="/invisalign" className="nav-link" style={{cursor:'pointer', whiteSpace:'nowrap', width:'100%', display:'inline-block'}} onClick={() => setMenuOpen(false)}>Invisalign</Link></li>
										<li style={{padding:'0.25rem 0'}}><Link to="/kids-dentistry" className="nav-link" style={{cursor:'pointer', whiteSpace:'nowrap', width:'100%', display:'inline-block'}} onClick={() => setMenuOpen(false)}>Kids Dentistry</Link></li>
										<li style={{padding:'0.25rem 0'}}><Link to="/painless-canal-treatment" className="nav-link" style={{cursor:'pointer', whiteSpace:'nowrap', width:'100%', display:'inline-block'}} onClick={() => setMenuOpen(false)}>Painless Canal Treatment</Link></li>
										<li style={{padding:'0.25rem 0'}}><Link to="/proclain-teeth-veeners" className="nav-link" style={{cursor:'pointer', whiteSpace:'nowrap', width:'100%', display:'inline-block'}} onClick={() => setMenuOpen(false)}>Proclain Teeth Veeners</Link></li>
										<li style={{padding:'0.25rem 0'}}><Link to="/smile-makeover" className="nav-link" style={{cursor:'pointer', whiteSpace:'nowrap', width:'100%', display:'inline-block'}} onClick={() => setMenuOpen(false)}>Smile Make Over</Link></li>
										<li style={{padding:'0.25rem 0'}}><Link to="/teeth-cleaning" className="nav-link" style={{cursor:'pointer', whiteSpace:'nowrap', width:'100%', display:'inline-block'}} onClick={() => setMenuOpen(false)}>Teeth Cleaning</Link></li>
										<li style={{padding:'0.25rem 0'}}><Link to="/teeth-whitening-treatment" className="nav-link" style={{cursor:'pointer', whiteSpace:'nowrap', width:'100%', display:'inline-block'}} onClick={() => setMenuOpen(false)}>Teeth Whitening</Link></li>
										<li style={{padding:'0.25rem 0'}}><Link to="/tooth-filling" className="nav-link" style={{cursor:'pointer', whiteSpace:'nowrap', width:'100%', display:'inline-block'}} onClick={() => setMenuOpen(false)}>Tooth Filling</Link></li>
										<li style={{padding:'0.25rem 0'}}><Link to="/tooth-removal" className="nav-link" style={{cursor:'pointer', whiteSpace:'nowrap', width:'100%', display:'inline-block'}} onClick={() => setMenuOpen(false)}>Tooth Removal</Link></li>
									</ul>
								</div>
							</div>
				<Link to="/our-team" className="nav-link" style={{cursor:'pointer'}} onClick={() => setMenuOpen(false)}>Our Team</Link>
				<Link to="/holistic-dentist" className="nav-link" style={{cursor:'pointer'}} onClick={() => setMenuOpen(false)}>Holistic Dentist</Link>
				<Link to="/happy-patients" className="nav-link" style={{cursor:'pointer'}} onClick={() => setMenuOpen(false)}>Happy Patients</Link>
				<Link to="/clinic-tour" className="nav-link" style={{cursor:'pointer'}} onClick={() => setMenuOpen(false)}>Clinic Tour</Link>
				<Link to="/dental-tourism" className="nav-link" style={{cursor:'pointer'}} onClick={() => setMenuOpen(false)}>Dental Tourism</Link>
				<Link to="/cases-pictures" className="nav-link" style={{cursor:'pointer'}} onClick={() => setMenuOpen(false)}>Cases Pictures</Link>
				<Link to="/book-online" className="nav-link" style={{cursor:'pointer'}} onClick={() => setMenuOpen(false)}>Book Online</Link>
			</nav>
				<style>{`
					.dropdown-trigger:hover .dropdown-menu,
					.dropdown-menu:hover {
						display: block !important;
					}
					.dropdown-trigger .dropdown-menu {
						display: none;
					}
					.nav-link, .dropdown-trigger {
						cursor: pointer !important;
					}
				`}</style>
		</header>
	);
}

export default Header;
