// Placeholder image for services
const servicePlaceholder = 'https://via.placeholder.com/80x60?text=Service';

function ServicesSlider() {
	const [current, setCurrent] = React.useState(0);
		const visible = 3;
	const total = services.length;
		const next = () => setCurrent((c) => (c + visible < total ? c + visible : c));
		const prev = () => setCurrent((c) => (c - visible >= 0 ? c - visible : 0));
	const goTo = (idx) => setCurrent(idx);
	return (
		<div className="w-full flex flex-col items-center">
			<div className="flex items-center justify-center gap-4 w-full">
				<button onClick={prev} className="bg-white border border-gray-300 text-red-700 rounded-full p-3 shadow-lg hover:bg-red-100 transition">
					&#8592;
				</button>
				<div className="flex gap-8">
					{services.slice(current, current + visible).map((service, idx) => {
						let imgSrc;
						try {
							imgSrc = require(`../assets/${service.name.replace(/ /g, ' ').toLowerCase()}.png`);
						} catch {
							imgSrc = servicePlaceholder;
						}
						return (
							<div key={service.name} className="bg-white rounded-2xl shadow-xl px-8 py-12 w-[340px] h-[420px] flex flex-col border border-gray-100 transition-transform duration-300 hover:scale-105" style={{ boxShadow: '0 4px 32px 0px rgba(255,0,0,0.10), 0 0 40px 0px rgba(0,0,255,0.12)' }}>
								<img src={imgSrc} alt={service.name} className="mx-auto -mt-4 mb-2 w-32 h-28 object-contain" />
								<h3 className="text-lg font-bold text-red-700 mb-2 text-center">{service.name}</h3>
								<ul className="text-gray-700 text-left mb-6 list-disc list-inside flex-1">
									{service.bullets.map((b, i) => <li key={i}>{b}</li>)}
								</ul>
								<div className="flex justify-center w-full">
									<button className="w-2/3 py-2 rounded-full bg-red-500 text-white font-semibold shadow-lg hover:bg-white hover:text-red-600 border-2 border-red-500 hover:scale-105 transition-transform text-base">
										Consult Now
									</button>
								</div>
							</div>
						);
					})}
				</div>
				<button onClick={next} className="bg-white border border-gray-300 text-red-700 rounded-full p-3 shadow-lg hover:bg-red-100 transition">
					&#8594;
				</button>
			</div>
					<div className="flex justify-center mt-8 gap-2">
						{Array.from({ length: 5 }).map((_, idx) => (
							<button
								key={idx}
								onClick={() => goTo(idx * visible)}
								className={`w-3 h-3 rounded-full ${current === idx * visible ? 'bg-red-500' : 'bg-gray-300'} transition`}
								aria-label={`Go to slide ${idx + 1}`}
							/>
						))}
					</div>
		</div>
	);
}

// Animated counting component
function AnimatedCount({ end, className }) {
	const [count, setCount] = React.useState(0);
	React.useEffect(() => {
		let start = 0;
		const duration = 1200;
		const increment = end > 1000 ? Math.ceil(end / 60) : 1;
		const stepTime = Math.max(Math.floor(duration / end), 20);
		const timer = setInterval(() => {
			start += increment;
			if (start >= end) {
				setCount(end);
				clearInterval(timer);
			} else {
				setCount(start);
			}
		}, stepTime);
		return () => clearInterval(timer);
	}, [end]);
	return <div className={className}>{count}{[16, 25, 15000].includes(end) ? '+' : ''}</div>;
}

