import { useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import seoConfig from '../seo';

function setMeta(name, content) {
  let el = document.querySelector(`meta[name="${name}"]`);
  if (!el) {
    el = document.createElement('meta');
    el.setAttribute('name', name);
    document.head.appendChild(el);
  }
  el.setAttribute('content', content || '');
}

function setMetaProperty(prop, content) {
  let el = document.querySelector(`meta[property="${prop}"]`);
  if (!el) {
    el = document.createElement('meta');
    el.setAttribute('property', prop);
    document.head.appendChild(el);
  }
  el.setAttribute('content', content || '');
}

function setLinkRel(rel, href) {
  let el = document.querySelector(`link[rel="${rel}"]`);
  if (!el) {
    el = document.createElement('link');
    el.setAttribute('rel', rel);
    document.head.appendChild(el);
  }
  el.setAttribute('href', href || '');
}

export default function SEO() {
  const location = useLocation();

  useEffect(() => {
    const path = location.pathname;
    const conf = seoConfig[path] || {};
    if (conf.title) document.title = conf.title;
    if (conf.description) setMeta('description', conf.description);
    if (conf.keywords) setMeta('keywords', conf.keywords);
    // Open Graph
    if (conf.og) {
      setMetaProperty('og:title', conf.og.title || conf.title);
      setMetaProperty('og:description', conf.og.description || conf.description);
      if (conf.og.image) setMetaProperty('og:image', conf.og.image);
    }
    // Twitter
    if (conf.twitter) {
      if (conf.twitter.card) setMeta('twitter:card', conf.twitter.card);
      if (conf.twitter.site) setMeta('twitter:site', conf.twitter.site);
      if (conf.twitter.creator) setMeta('twitter:creator', conf.twitter.creator);
    }
    // Canonical
    if (conf.canonical) setLinkRel('canonical', conf.canonical);
    // Robots
    if (conf.robots) setMeta('robots', conf.robots);
    // JSON-LD
    const existingLd = document.getElementById('seo-json-ld');
    if (existingLd) existingLd.remove();
    if (conf.jsonLd) {
      const script = document.createElement('script');
      script.type = 'application/ld+json';
      script.id = 'seo-json-ld';
      script.text = JSON.stringify(conf.jsonLd);
      document.head.appendChild(script);
    }
  }, [location]);

  return null;
}
